/**
 * Fills a dataset with example content: site settings, pages that use every
 * block, and three collections (Blog, Gallery, Projects) with entries and authors.
 *
 *   pnpm seed              # refuses to run when content already exists
 *   pnpm seed --replace    # deletes existing pages, collections, entries,
 *                          # authors and settings first
 *
 * Photos are downloaded from picsum.photos (Unsplash license) and uploaded to
 * the dataset. Document IDs are generated by Sanity; references use the IDs
 * returned when each document is created.
 */
import { randomUUID } from 'node:crypto'
import { getCliClient } from 'sanity/cli'

const client = getCliClient({ apiVersion: '2026-10-01' })
const replace = process.argv.includes('--replace')

// "post" and "gallery" are document types from earlier versions of the template
// translation.metadata links translations; it goes with the documents it references
const CONTENT_TYPES = ['page', 'collection', 'entry', 'author', 'settings', 'translation.metadata', 'post', 'gallery']

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const key = () => randomUUID().replaceAll('-', '').slice(0, 12)
const ref = (_ref: string) => ({ _type: 'reference', _ref, _key: key() })
// Entries copy the fields their collection uses ("Entry fields" → "sections")
const ENTRY_FIELDS = {
  blog: ['body', 'authors'],
  gallery: ['images'],
  projects: ['body', 'images', 'blocks', 'details']
}
const collectionSections = new Map<string, string[]>()
const belongsTo = (_ref: string) => ({ collection: { _type: 'reference', _ref }, sections: collectionSections.get(_ref) })
const slug = (current: string) => ({ _type: 'slug', current })

type Link = Record<string, unknown>
const external = (label: string, href: string, extra: Link = {}): Link =>
  ({ _type: 'link', _key: key(), label, linkType: 'external', href, newTab: false, color: 'primary', variant: 'solid', ...extra })
const internal = (label: string, id: string, extra: Link = {}): Link =>
  ({ _type: 'link', _key: key(), label, linkType: 'internal', page: { _type: 'reference', _ref: id }, newTab: false, color: 'primary', variant: 'solid', ...extra })

// Portable Text. Use **bold**, *italic*, `code` and [label](url) inside strings.
function block(text: string, style = 'normal', extra: Record<string, unknown> = {}) {
  const markDefs: Record<string, unknown>[] = []
  const children: Record<string, unknown>[] = []
  const pattern = /\*\*(.+?)\*\*|\*(.+?)\*|`(.+?)`|\[(.+?)\]\((.+?)\)/g
  let last = 0
  for (const match of text.matchAll(pattern)) {
    if (match.index > last) children.push({ _type: 'span', _key: key(), text: text.slice(last, match.index), marks: [] })
    if (match[1]) children.push({ _type: 'span', _key: key(), text: match[1], marks: ['strong'] })
    else if (match[2]) children.push({ _type: 'span', _key: key(), text: match[2], marks: ['em'] })
    else if (match[3]) children.push({ _type: 'span', _key: key(), text: match[3], marks: ['code'] })
    else if (match[4]) {
      const markKey = key()
      markDefs.push({ _type: 'link', _key: markKey, href: match[5], newTab: match[5]!.startsWith('http') })
      children.push({ _type: 'span', _key: key(), text: match[4], marks: [markKey] })
    }
    last = match.index + match[0].length
  }
  if (last < text.length) children.push({ _type: 'span', _key: key(), text: text.slice(last), marks: [] })
  return { _type: 'block', _key: key(), style, markDefs, children, ...extra }
}
const h2 = (text: string) => block(text, 'h2')
const h3 = (text: string) => block(text, 'h3')
const bullets = (items: string[]) => items.map(item => block(item, 'normal', { listItem: 'bullet', level: 1 }))
const numbered = (items: string[]) => items.map(item => block(item, 'normal', { listItem: 'number', level: 1 }))
const callout = (title: string, description: string, color = 'info', icon = 'i-lucide-info') =>
  ({ _type: 'callout', _key: key(), title, description, color, icon, variant: 'subtle' })
// Code blocks use the "code" type from @sanity/code-input
const code = (filename: string, source: string, language = 'typescript', highlightedLines?: number[]) =>
  ({ _type: 'code', _key: key(), filename, language, code: source, ...(highlightedLines ? { highlightedLines } : {}) })
const codeGroup = (...tabs: ReturnType<typeof code>[]) => ({ _type: 'codeGroup', _key: key(), tabs })

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

const uploaded = new Map<number, { _id: string, author: string }>()

async function photo(id: number, width = 1600, height = 1067) {
  if (!uploaded.has(id)) {
    const info = await fetch(`https://picsum.photos/id/${id}/info`).then(res => res.json() as Promise<{ author: string }>)
    const response = await fetch(`https://picsum.photos/id/${id}/${width}/${height}.jpg`)
    if (!response.ok) throw new Error(`Could not download picsum photo ${id}`)
    const asset = await client.assets.upload('image', Buffer.from(await response.arrayBuffer()), {
      filename: `picsum-${id}.jpg`,
      creditLine: `${info.author} / Unsplash`
    })
    uploaded.set(id, { _id: asset._id, author: info.author })
    console.log(`  uploaded photo ${id} by ${info.author}`)
  }
  return uploaded.get(id)!
}

async function image(id: number, alt?: string, caption?: string) {
  const asset = await photo(id)
  return {
    _type: 'image',
    asset: { _type: 'reference', _ref: asset._id },
    alt: alt ?? `Photo by ${asset.author}`,
    ...(caption ? { caption } : {})
  }
}

async function galleryImages(ids: number[]) {
  return Promise.all(ids.map(async id => ({ _key: key(), ...(await image(id, undefined, `Photo by ${(await photo(id)).author} on Unsplash`)) })))
}

// The example content is in English, the site language set in Site Settings
const LOCALIZED_TYPES = ['page', 'collection', 'entry']

async function create<T extends Record<string, unknown>>(doc: T) {
  const language = LOCALIZED_TYPES.includes(doc._type as string) ? { language: 'en' } : {}
  const created = await client.create({ ...doc, ...language } as T & { _type: string })
  console.log(`  created ${doc._type}: ${(doc.title ?? doc.name) as string}`)
  return created._id
}

// ---------------------------------------------------------------------------
// Seed
// ---------------------------------------------------------------------------

async function clearExisting() {
  const ids = await client.fetch<string[]>(`*[_type in $types]._id`, { types: CONTENT_TYPES }, { perspective: 'raw' })
  if (!ids.length) return
  if (!replace) {
    console.error(`The dataset already has ${ids.length} documents of type ${CONTENT_TYPES.join(', ')}.`)
    console.error('Run "pnpm seed --replace" to delete them and seed again.')
    process.exit(1)
  }
  console.log(`Deleting ${ids.length} existing documents…`)
  const tx = client.transaction()
  ids.forEach(id => tx.delete(id))
  await tx.commit({ visibility: 'async' })
}

